export class BudgetCalculatorEngine{constructor(e={}){this.totalBudget=e.totalBudget||1e4,this.currency=e.currency||"INR",this.expenses=e.expenses||[]}addExpense(e,t,n="general"){if(!e||"number"!=typeof t||t<=0)return null;const s={id:"exp_"+Date.now()+"_"+Math.random().toString(36).substring(2,6),title:e,amount:t,category:n};return this.expenses.push(s),s}removeExpense(e){const t=this.expenses.findIndex(t=>t.id===e);return-1!==t?this.expenses.splice(t,1)[0]:null}getTotalSpent(){return this.expenses.reduce((e,t)=>e+t.amount,0)}getRemainingBudget(){return this.totalBudget-this.getTotalSpent()}getCategoryBreakdown(){const e={};return this.expenses.forEach(t=>{e[t.category]=(e[t.category]||0)+t.amount}),e}getBudgetHealth(){const e=this.getTotalSpent()/(this.totalBudget||1);return e>1?{status:"exceeded",ratio:e,message:"Over Budget"}:e>=.85?{status:"warning",ratio:e,message:"Near Budget Cap"}:{status:"healthy",ratio:e,message:"Within Budget"}}formatCurrency(e,t=this.currency){return"INR"===t?"₹"+e.toLocaleString("en-IN"):`${t} ${e.toFixed(2)}`}}